########## EnsureUniqueTelephone.java ##########
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;

/**
 * Rejects a new owner whose normalized telephone (set by {@link BuildOwner}) already belongs to
 * another owner. Runs after Build and before Save so the conflict is a 409, not a persisted duplicate.
 */
public class EnsureUniqueTelephone {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) throws DuplicateTelephoneException {
        String telephone = owner.getTelephone();
        for (Owner existing : ownerRepository.findAll()) {
            if (telephone.equals(existing.getTelephone())) {
                throw new DuplicateTelephoneException(telephone);
            }
        }
    }
}

########## EnsureUniqueHousehold.java ##########
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;

/**
 * Rejects a new owner whose last name and address already belong to another owner, comparing both
 * case-insensitively with collapsed whitespace. Skipped when the request opts in with
 * {@code sharesHousehold: true}. Runs after Build and before Save so the conflict is a 409, not a
 * persisted duplicate.
 */
public class EnsureUniqueHousehold {

    public void service(@Val Owner owner, @Val Boolean sharesHousehold, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(sharesHousehold)) {
            return;
        }
        String lastName = normalize(owner.getLastName());
        String address = normalize(owner.getAddress());
        for (Owner existing : ownerRepository.findAll()) {
            if (lastName.equals(normalize(existing.getLastName()))
                    && address.equals(normalize(existing.getAddress()))) {
                throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
            }
        }
    }

    private static String normalize(String value) {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}

########## AssignHousehold.java ##########
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * When the request opts in with {@code sharesHousehold: true}, gives the new owner a stable shared
 * {@code householdId} derived from the household's normalized last name and address, and back-fills
 * the same id onto any existing owner in that household that lacks one. Deterministic derivation means
 * every owner joining the same household is assigned an identical, non-blank identifier. Runs after
 * {@link EnsureUniqueHousehold} and before the owner is saved.
 */
public class AssignHousehold {

    public void service(@Val Owner owner, @Val Boolean sharesHousehold, OwnerRepository ownerRepository) {
        if (!Boolean.TRUE.equals(sharesHousehold)) {
            return;
        }
        String householdId = deriveId(owner.getLastName(), owner.getAddress());
        owner.setHouseholdId(householdId);
        for (Owner existing : ownerRepository.findAll()) {
            if (existing.getHouseholdId() == null && sameHousehold(owner, existing)) {
                existing.setHouseholdId(householdId);
                ownerRepository.save(existing);
            }
        }
    }

    private static boolean sameHousehold(Owner a, Owner b) {
        return normalize(a.getLastName()).equals(normalize(b.getLastName()))
                && normalize(a.getAddress()).equals(normalize(b.getAddress()));
    }

    /** Stable {@code HH-<12 hex>} identifier for the household keyed by normalized last name and address. */
    private static String deriveId(String lastName, String address) {
        String key = normalize(lastName) + "|" + normalize(address);
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder("HH-");
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException(ex);
        }
    }

    private static String normalize(String value) {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}

########## AssignCustomerCode.java ##########
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's {@code customerCode} as {@code <CITY3>-<LAST3>-<NNNN>}: the upper-cased first
 * three letters of the city and last name, and a per-city 4-digit sequence one more than the owners
 * already in that city. Runs before the owner is saved, so the sequence excludes the owner being
 * created.
 */
public class AssignCustomerCode {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String city3 = three(owner.getCity());
        String last3 = three(owner.getLastName());
        long inCity = ownerRepository.findAll().stream()
            .filter(o -> owner.getCity().equalsIgnoreCase(o.getCity())).count();
        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, inCity + 1));
    }

    private static String three(String value) {
        return value.substring(0, Math.min(3, value.length())).toUpperCase();
    }
}

########## CountNamesakes.java ##########
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Records the owner's {@code namesakeCount}: the number of existing owners sharing its first and last
 * name, compared case-insensitively. Runs before the owner is saved, so it counts only the owners that
 * existed before this create.
 */
public class CountNamesakes {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String firstName = owner.getFirstName();
        String lastName = owner.getLastName();
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (firstName.equalsIgnoreCase(existing.getFirstName())
                    && lastName.equalsIgnoreCase(existing.getLastName())) {
                count++;
            }
        }
        owner.setNamesakeCount(count);
    }
}

########## EnsureCityCapacity.java ##########
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;

/**
 * Rejects a new owner whose city already contains {@value #CAPACITY} or more owners, comparing city
 * names case-insensitively. Runs before Save so a full city is a 409, not a persisted overflow.
 */
public class EnsureCityCapacity {

    private static final int CAPACITY = 50;

    public void service(@Val Owner owner, OwnerRepository ownerRepository) throws CityAtCapacityException {
        String city = owner.getCity();
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (city != null && city.equalsIgnoreCase(existing.getCity())) {
                count++;
            }
        }
        if (count >= CAPACITY) {
            throw new CityAtCapacityException(city, count);
        }
    }
}

